import hashlib,json
from pathlib import Path
R=Path(__file__).resolve().parent;ROOT=R.parents[1]
read=lambda p:json.loads(p.read_text())
f=read(R/'freeze.json');a=read(R/'audit.json');ann=read(R/'annotations.json');res=read(R/'results.json');w=read(R/'witnesses.json');packets=[read(p) for p in (R/'packets').glob('*.json')]
checks={'frozen_hashes':all(hashlib.sha256((ROOT/p).read_bytes()).hexdigest()==h for p,h in f['files'].items()),'source_and_configuration_identity':a['staged_source_identity'] and a['staged_configuration_identity'],'equal_source_and_observation_caps':a['source_cap_valid'] and a['observation_cap_valid'],'all_logical_reviews_annotated':len(ann)==len(a['rows'])==48 and set(ann)=={x['run_id'] for x in a['rows']},'physical_call_count':sum(x['calls'] for x in a['operational'].values())==f['planned_physical_calls']==33,'all_transport_and_schema_valid':not a['invalid'] and all(x['calls']==x['transport_ok'] and x['tools']==0 and x['usage_missing']==0 for x in a['operational'].values()),'shared_inputs_identical':len(f['shared_identical_inputs'])==15 and all(p['AST']==p['LSP'] and p['AST_observations']==p['LSP_observations'] for p in packets if p['case_id']+'_'+p['world']+'_lsp' in f['shared_identical_inputs']),'actual_native_requests':a['native_definition_requests']==288 and a['query_resolution']['lsp_server_error']==0,'native_outcome_accounting':sum(a['native_outcomes'].values())==288,'witnesses_success_and_repeat':len(w)==48 and all(x['ok'] and x['exit_code']==0 for x in w),'primary_and_diagnostic_split':all(x['total_pairs']==11 for x in res['summary']['external_repository_pr_derived'].values()) and all(x['total_pairs']==1 for x in res['summary']['code_generation_format_diagnostic'].values())}
for row in read(R/'selected.json'):
 iid=row['instance_id'];pairs={rev:[x['observation'] for x in w if x['instance_id']==iid and x['revision']==rev] for rev in ['original','fixed']}
 checks['witnesses_success_and_repeat'] &= all(len(v)==2 and v[0]==v[1] for v in pairs.values()) and pairs['original'][0]!=pairs['fixed'][0]
checks['original_auditor_preserved']=read(R/'audit_original.json')['invalid']==['E06_a_ast'] and hashlib.sha256((R/'audit.py').read_bytes()).hexdigest()==f['files'][str((R/'audit.py').relative_to(ROOT))]
result={'passed':all(checks.values()),'checks':checks,'note':'Validates saved source/evidence and accounting. Does not rerun the model, LSP or complete SWE-bench harness.'};(R/'validation.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2));assert result['passed']
